import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  defaultValue?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAY_LABELS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

const MONTH_LABELS = [
  'Январь',
  'Февраль',
  'Март',
  'Апрель',
  'Май',
  'Июнь',
  'Июль',
  'Август',
  'Сентябрь',
  'Октябрь',
  'Ноябрь',
  'Декабрь',
];

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function shiftDays(date: Date, amount: number): Date {
  const next = startOfDay(date);
  next.setDate(next.getDate() + amount);
  return next;
}

function shiftMonths(date: Date, amount: number): Date {
  return new Date(date.getFullYear(), date.getMonth() + amount, 1);
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function buildMonthGrid(month: Date): Date[] {
  const firstDay = new Date(month.getFullYear(), month.getMonth(), 1);
  const leadingBlanks = (firstDay.getDay() + 6) % 7;
  const gridStart = shiftDays(firstDay, -leadingBlanks);
  return Array.from({ length: 42 }, (_, index) => shiftDays(gridStart, index));
}

function formatFullDate(date: Date): string {
  return `${date.getDate()} ${MONTH_LABELS[date.getMonth()]} ${date.getFullYear()}`;
}

export default function ReportDatePicker({
  value,
  defaultValue,
  onChange,
}: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [internalValue, setInternalValue] = useState<Date>(() =>
    startOfDay(defaultValue ?? new Date()),
  );

  const selected = value ? startOfDay(value) : internalValue;

  const [visibleMonth, setVisibleMonth] = useState<Date>(
    () => new Date(selected.getFullYear(), selected.getMonth(), 1),
  );

  const days = useMemo(() => buildMonthGrid(visibleMonth), [visibleMonth]);

  const quickOptions = useMemo(
    () => [
      { id: 'today', label: 'Сегодня', date: today },
      { id: 'yesterday', label: 'Вчера', date: shiftDays(today, -1) },
      { id: 'week-ago', label: 'Неделя назад', date: shiftDays(today, -7) },
    ],
    [today],
  );

  const selectDate = (date: Date) => {
    const normalized = startOfDay(date);
    setInternalValue(normalized);
    setVisibleMonth(new Date(normalized.getFullYear(), normalized.getMonth(), 1));
    onChange(normalized);
  };

  return (
    <section
      className="jx-card"
      aria-label="Выбор даты отчёта"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4, 16px)',
        padding: 'var(--jx-space-4, 16px)',
        borderRadius: 'var(--jx-radius, 4px)',
        inlineSize: 'fit-content',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2, 8px)' }}
      >
        {quickOptions.map((option) => (
          <Button
            key={option.id}
            type="button"
            aria-pressed={isSameDay(option.date, selected)}
            onClick={() => selectDate(option.date)}
          >
            {option.label}
          </Button>
        ))}
      </div>

      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3, 12px)',
        }}
      >
        <Button
          type="button"
          aria-label="Предыдущий месяц"
          onClick={() => setVisibleMonth((month) => shiftMonths(month, -1))}
        >
          ←
        </Button>
        <strong aria-live="polite" style={{ color: 'var(--jx-fg, inherit)' }}>
          {MONTH_LABELS[visibleMonth.getMonth()]} {visibleMonth.getFullYear()}
        </strong>
        <Button
          type="button"
          aria-label="Следующий месяц"
          onClick={() => setVisibleMonth((month) => shiftMonths(month, 1))}
        >
          →
        </Button>
      </header>

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(7, minmax(var(--jx-space-8, 40px), 1fr))',
          gap: 'var(--jx-space-1, 4px)',
        }}
      >
        {WEEKDAY_LABELS.map((weekday) => (
          <span
            key={weekday}
            aria-hidden="true"
            style={{
              textAlign: 'center',
              color: 'var(--jx-fg-muted, inherit)',
              fontSize: 'var(--jx-font-size-sm, 0.85em)',
              paddingBlock: 'var(--jx-space-1, 4px)',
            }}
          >
            {weekday}
          </span>
        ))}

        {days.map((day) => {
          const isSelected = isSameDay(day, selected);
          const isOutsideMonth = day.getMonth() !== visibleMonth.getMonth();

          return (
            <Button
              key={day.toISOString()}
              type="button"
              aria-label={formatFullDate(day)}
              aria-pressed={isSelected}
              aria-current={isSameDay(day, today) ? 'date' : undefined}
              onClick={() => selectDate(day)}
              style={{
                inlineSize: '100%',
                opacity: isOutsideMonth ? 0.45 : 1,
                outline: isSelected ? '2px solid var(--jx-accent, currentColor)' : undefined,
                outlineOffset: 'var(--jx-space-05, 2px)',
              }}
            >
              {day.getDate()}
            </Button>
          );
        })}
      </div>

      <p style={{ margin: 0, color: 'var(--jx-fg-muted, inherit)' }}>
        Дата отчёта: {formatFullDate(selected)}
      </p>
    </section>
  );
}

